<?php
return static function(Database $db): void {
 $p=$db->pdo;$p->exec("CREATE TABLE IF NOT EXISTS unlock_requests (id VARCHAR(64) PRIMARY KEY,pc_id VARCHAR(64) NOT NULL,challenge VARCHAR(255) NOT NULL,approval_token_hash CHAR(64) NULL,status ENUM('PENDING','APPROVED','REJECTED','EXPIRED','CANCELLED') NOT NULL DEFAULT 'PENDING',winning_device_id VARCHAR(64) NULL,winning_transport VARCHAR(32) NULL,signature_b64 TEXT NULL,biometric VARCHAR(64) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at BIGINT NOT NULL,approved_at TIMESTAMP NULL,completed_at TIMESTAMP NULL,UNIQUE KEY uq_requests_approval_token_hash(approval_token_hash),KEY idx_requests_pc_status_exp(pc_id,status,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$p->exec("CREATE TABLE IF NOT EXISTS unlock_request_candidates (request_id VARCHAR(64) NOT NULL,device_id VARCHAR(64) NOT NULL,state ENUM('PENDING','APPROVED','REJECTED','EXPIRED','LATE') NOT NULL DEFAULT 'PENDING',notified_at TIMESTAMP NULL,seen_at TIMESTAMP NULL,responded_at TIMESTAMP NULL,PRIMARY KEY(request_id,device_id),KEY idx_candidates_device_state(device_id,state)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $exists=(int)$p->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='unlock_sessions' AND table_type='BASE TABLE'")->fetchColumn();if($exists){foreach($p->query('SELECT * FROM unlock_sessions')->fetchAll() as $s){$db->exec('INSERT IGNORE INTO unlock_requests(id,pc_id,challenge,approval_token_hash,status,winning_device_id,signature_b64,biometric,expires_at,approved_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$s['id'],$s['pc_id'],$s['challenge'],$s['approval_token_hash']??null,$s['status'],$s['device_id'],$s['signature_b64']??null,$s['biometric']??null,$s['expires_at'],$s['approved_at']??null,$s['created_at']]);$db->exec('INSERT IGNORE INTO unlock_request_candidates(request_id,device_id,state) VALUES(?,?,?)',[$s['id'],$s['device_id'],$s['status']==='APPROVED'?'APPROVED':'PENDING']);}$p->exec('RENAME TABLE unlock_sessions TO unlock_sessions_legacy_v1');}$p->exec('CREATE OR REPLACE VIEW unlock_sessions AS SELECT id,pc_id,winning_device_id device_id,challenge,approval_token_hash,expires_at,status,signature_b64,biometric,approved_at,created_at FROM unlock_requests');
};
